import{_ as t,o,c as a,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const k=JSON.parse('{"title":"FR 3.6.4 — List Task View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-4-list-task-view/spec.md","filePath":"feature/srs/05-content-task-workflow/3-6-4-list-task-view/spec.md"}'),r={name:"feature/srs/05-content-task-workflow/3-6-4-list-task-view/spec.md"};function c(i,e,n,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-6-4-—-list-task-view" tabindex="-1">FR 3.6.4 — List Task View <a class="header-anchor" href="#fr-3-6-4-—-list-task-view" aria-label="Permalink to &quot;FR 3.6.4 — List Task View&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.6.4</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-056</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">List Task View</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Content &amp; Workflow (<code>FR 3.6</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-33</code></td></tr><tr><td style="text-align:left;"><strong>Document Status</strong></td><td style="text-align:left;">Implemented &amp; Verified</td></tr></tbody></table><h2 id="_1-objective-functional-scope" tabindex="-1">1. Objective &amp; Functional Scope <a class="header-anchor" href="#_1-objective-functional-scope" aria-label="Permalink to &quot;1. Objective &amp; Functional Scope&quot;">​</a></h2><p>Xem và thao tác danh sách công việc dạng bảng chi tiết (List Task View — /workspaces/:id/tasks?view=list). Hiển thị đầy đủ các cột Mã Task, Tiêu đề, Trạng thái, Người thực hiện, Nền tảng, Mức độ ưu tiên, Hạn chót; hỗ trợ sắp xếp theo cột và kéo thả thay đổi thứ tự ưu tiên trong Backlog (BR-33).</p><p><strong>Consolidated Implementation Scope:</strong> Renders the real MongoDB <code>tasks</code> collection (<code>Campaign</code> deliverables, accepted <code>CONTENT_REQUEST</code> tasks, and standalone manual tasks) in a sortable, paginated tabular view with deterministic <code>(sortField, _id)</code> tie-breaking, inline status/priority/assignee badges, URL-synced <code>?task=&lt;id&gt;</code> right-panel inspection, and zero synthetic mock fallbacks (<code>BR-33</code>).</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized actor (<code>Owner, Manager, Creator, Client</code>), I want to execute <strong>List Task View</strong> within my active Workspace with strict role/audience isolation, version/concurrency safety, and responsive feedback, so that content production workflows satisfy <code>BR-33</code> across Web and Mobile.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace &amp; Role Authorization:</strong> Only authenticated actors holding <code>Owner, Manager, Creator, Client</code> in the target Workspace (plus <code>Guest</code> solely on public survey token endpoints in <code>3.6.25</code>) may invoke <code>GET /api/v1/workspaces/{workspaceId}/tasks · POST /api/v1/workspaces/{workspaceId}/tasks/standalone · DELETE /api/v1/workspaces/{workspaceId}/tasks/{taskId}</code>; revoked or cross-workspace callers are rejected (<code>401</code> / <code>403</code>).</li><li><strong>Core Domain &amp; Security Invariants (<code>BR-33, BR-34</code>):</strong> <code>TaskServiceImpl, WorkspaceTaskReader, TaskLifecycle</code> enforces all state-machine locks, audience visibility filters (<code>INTERNAL</code> vs per-<code>clientProfileId</code> <code>CLIENT</code>), storage/file validation rules, and Workspace timezone boundaries (<code>Asia/Ho_Chi_Minh</code> default): <ul><li><strong>Bulk Status Anti-Bypass (<code>TaskBulkActionBar</code>):</strong> Bulk status mutation (<code>PATCH /tasks/{taskId}/status</code>) prohibits jumping directly to <code>IN_REVIEW</code> or <code>FINISHED</code> (<code>409 TASK_WORKFLOW_REQUIRED</code>) and restricts <code>CANCELLED</code> strictly to <code>Owner</code> and <code>Manager</code> (<a href="./../../../../ba/13-task-status-and-approval-governance.html">BA Governance</a>).</li><li><strong>Real-Time Row Sync:</strong> Completing section/task approvals inside <code>TaskDetailPanel</code> (Side Peek / Center Modal) triggers <code>onUpdated</code> immediately so outer table status badges transition from <code>IN_PROGRESS</code> / <code>IN_REVIEW</code> to <code>FINISHED</code> without manual refresh.</li></ul></li><li><strong>Persistence &amp; Envelope Contract:</strong> Operations on MongoDB <code>tasks</code> (<code>workspaceId</code>, <code>campaignId</code>, <code>sourceType</code>, <code>sourceRefId</code>, <code>type</code>, <code>status</code>, <code>priority</code>, <code>assigneeId</code>, <code>dueDate</code>, <code>createdAt</code>) return standardized <code>ApiResponse&lt;T&gt;</code> payloads (or authenticated binary/WebSocket frames where applicable) with deterministic <code>ErrorCode</code> mappings (<code>400 VALIDATION_ERROR</code>, <code>403 WORKSPACE_ACCESS_DENIED</code>, <code>404 WORKSPACE_NOT_FOUND</code> (<code>BR-33</code>)).</li><li><strong>Internationalization (<code>vi</code> / <code>en</code>):</strong> Every label, badge, filter pill, modal prompt, empty state, and error toast uses parallel translation keys (<code>tasks.list.* / tasks.status.* / tasks.types.*</code>) in <code>src/i18n/locales/vi/*.json</code> and <code>en/*.json</code> — zero hardcoded UI text.</li><li><strong>Semantic Light/Dark Theme &amp; Accessibility:</strong> Web (<code>src/pages/tasks/index.tsx</code>, <code>src/pages/tasks/components/views/ListView.tsx</code>, <code>src/pages/tasks/components/{TaskPagination,QuickCreateTaskDialog,TaskBulkActionBar}.tsx</code>, <code>src/pages/tasks/hooks/useTasks.ts</code>) and Mobile (<code>src/screens/content/TaskListScreen.tsx</code>, <code>src/services/taskService.ts</code>) components use semantic CSS variables / <code>dark:</code> Tailwind tokens and <code>useTheme()</code> tokens, supporting keyboard navigation (<code>Enter</code>/<code>Escape</code>/focus return) and mobile viewports.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surface (<code>brandhub-web</code>):</strong> <code>src/pages/tasks/index.tsx</code>, <code>src/pages/tasks/components/views/ListView.tsx</code>, <code>src/pages/tasks/components/{TaskPagination,QuickCreateTaskDialog,TaskBulkActionBar}.tsx</code>, <code>src/pages/tasks/hooks/useTasks.ts</code></li><li><strong>Mobile Surface (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/TaskListScreen.tsx</code>, <code>src/services/taskService.ts</code></li><li><strong>Required UI States:</strong><ul><li><strong>Loading / Pending:</strong> Skeleton placeholders, progress indicators for uploads/imports, and disabled duplicate-submit triggers.</li><li><strong>Empty State:</strong> Clear localized explanation with role-appropriate CTA — never substituting synthetic mock items.</li><li><strong>Conflict / Warning:</strong> Preserves unsaved user drafts on <code>409</code> conflicts and surfaces inline warnings (such as <code>RAW</code> unedited photo badges or compliance warnings).</li><li><strong>Error / Retry:</strong> Actionable inline/banner error state with retry capability.</li></ul></li></ul><h2 id="_5-api-realtime-contract" tabindex="-1">5. API &amp; Realtime Contract <a class="header-anchor" href="#_5-api-realtime-contract" aria-label="Permalink to &quot;5. API &amp; Realtime Contract&quot;">​</a></h2><ul><li><strong>Endpoints / Channels:</strong> <code>GET /api/v1/workspaces/{workspaceId}/tasks · POST /api/v1/workspaces/{workspaceId}/tasks/standalone · DELETE /api/v1/workspaces/{workspaceId}/tasks/{taskId}</code></li><li><strong>Controllers (<code>brandhub-business-service</code>):</strong> <code>TaskController.getTasks() / createTask() / createStandaloneTask() / deleteTask()</code></li><li><strong>Services:</strong> <code>TaskServiceImpl, WorkspaceTaskReader, TaskLifecycle</code></li><li><strong>Repositories / Stores:</strong> TaskMongoRepository (MongoDB <code>tasks</code>), WorkspaceAccessService</li></ul><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Domain Error Codes:</strong> <code>400 VALIDATION_ERROR</code>, <code>403 WORKSPACE_ACCESS_DENIED</code>, <code>404 WORKSPACE_NOT_FOUND</code> (<code>BR-33</code>).</li><li><strong>Audience &amp; Removed-Member Isolation:</strong> Removed or deactivated Workspace members lose read/write/WebSocket access immediately on the next request or STOMP frame; <code>Client</code> actors never see <code>INTERNAL</code>-only materials or other <code>ClientProfile</code> assets.</li><li><strong>Idempotency &amp; Concurrency:</strong> Optimistic revision checks (<code>workflowRevision</code>, <code>revision</code>, <code>clientMessageId</code>, <code>DriveOperationLease</code>) prevent race-condition overwrites and duplicate records on retry.</li></ul><h2 id="_7-definition-of-done-cross-references" tabindex="-1">7. Definition of Done &amp; Cross-References <a class="header-anchor" href="#_7-definition-of-done-cross-references" aria-label="Permalink to &quot;7. Definition of Done &amp; Cross-References&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Backend endpoints/handlers verified by automated tests (<a href="./test.html">test.md</a>), Web &amp; Mobile UI integrated against live APIs, <code>vi</code>/<code>en</code> locale parity verified, and Light/Dark themes verified.</li><li><strong>Out of Scope:</strong> Adjacent workflow capabilities covered by sibling FRs in <code>3.6.1–3.6.35</code> and social publishing execution in <code>3.8.1–3.8.15</code>.</li><li><strong>Related Documentation:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA Content &amp; Workflow Spec</a> · <a href="./../../../../ba/12-state-machines.html">State Machines</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a> · <a href="./test.html">Test Suite</a>.</li></ul>',18)])])}const u=t(r,[["render",c]]);export{k as __pageData,u as default};
